func keyListDataSource() framework.ListDataSourceSpec[keyListModel] {
	return framework.ListDataSourceSpec[keyListModel]{
		TypeName: "_keys_keys",
		Schema:   keyListSchema(),
		List: func(ctx context.Context, client *core.Client, m *keyListModel) error {
			m.Keys = []keyItemModel{}
			page, err := firewallsv1.NewKeyClient(client).ListKeys(ctx, &firewallsv1.ListKeysRequest{Parent: "projects/" + m.Project.ValueString()})
			if err != nil {
				return err
			}
			for _, p := range page.GetKeys() {
				if p.GetState() == firewallsv1.Key_TERMINATED {
					continue
				}
				var item keyItemModel
				if err := keyItemFromProto(p, &item); err != nil {
					return err
				}
				m.Keys = append(m.Keys, item)
			}
			return nil
		},
	}
}
